  const respond = (data) => setResult(data);
  const cleanup = () => {};
  return { respond, cleanup };
}

// Test driver (leave as is): one effect run per query (cleaning up the previous),
// then responses arrive in arrivalOrder (indexes into queries).
function finalResult(queries, arrivalOrder) {
  let result = null;
  const runs = [];
  for (const q of queries) {
    if (runs.length) runs[runs.length - 1].cleanup();
    runs.push(runEffect(q, (r) => { result = r; }));
  }
  for (const i of arrivalOrder) runs[i].respond("results for " + queries[i]);
  return result;
}

