type Comment = { id: string; text: string; pending: boolean };

function optimisticReducer(list: Comment[], action: any): Comment[] {
  switch (action.type) {
    case "added":
      return [...list, { id: action.tempId, text: action.text, pending: true }];
    case "confirmed":
      return list.map((c) => (c.id === action.tempId ? { id: action.id, text: c.text, pending: false } : c));
    case "failed":
      return list.filter((c) => !c.pending);
    default:
      return list;
  }
}

